export const hostels = defineTable(
  'hostels',
  { module: 'M35', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    /** "Boys' hostel — Iqbal House" */
    name: text().notNull(),
    kind: enumText(hostelKinds).notNull(),
    wardenStaffId: uuid().references((): AnyPgColumn => staff.id),
    assistantWardenStaffId: uuid().references((): AnyPgColumn => staff.id),
    phone: text(),
    curfewTime: timeStr().notNull().default('20:00'),
    isActive: boolean().notNull().default(true),
  },
  (t) => [uniqueIndex('hostels_branch_name_uq').on(t.branchId, t.name).where(live(t))],
);

